export type UnitStatus = 'available' | 'reserved' | 'let';

export interface Unit {
  number: string;
  type: string;
  floor: number;
  sizeSqm: number;
  sizeSqft: number;
  bedrooms: number;
  bathrooms: number;
  status: UnitStatus;
  rentPerMonth: { kes: number; usd: number } | null;
}

export interface EstateItem {
  name: string;
  description: string;
}

export const RATES = estate.rates;
export const UNITS = estate.units as Unit[];
export const SERVICES: EstateItem[] = estate.services;
export const AMENITIES: EstateItem[] = estate.amenities;

